using J=nlohmann::json;namespace fs=std::filesystem;
void require(bool pass,const char* reason){if(!pass)throw std::runtime_error(std::string("candidate collection NOT_READY: ")+reason);}
bool yes(const J& j,const char* key){return j.contains(key)&&j.at(key).is_boolean()&&j.at(key).get<bool>();}
J envelope(const CandidateCollectionInputs& inputs,const char* schema){const auto& c=inputs.context();return {{"schema",schema},{"evidence_kind","actual"},{"source_commit",c.at("source_commit")},{"candidate_binary_sha256",c.at("candidate_binary_sha256")},{"profile_sha256",c.at("profile_sha256")},{"capability_sha256",c.at("capability_sha256")},{"producer_binary",inputs.documents().at("input").at("candidate_binary")},{"pass",false},{"live_ready",false},{"qualification_issued",false},{"gameplay_files_created",0},{"source_absolute_age",nullptr},{"clock_domain","host_qpc_ns"}};}
void fresh_output(const fs::path& p){require(!p.empty()&&fs::is_directory(fs::absolute(p).parent_path())&&!fs::exists(p),"fresh output in an existing directory required");}
void write_output(const fs::path& p,const J& value){const auto body=value.dump(2)+"\n";require(body.size()<=256*1024,"bounded metadata output exceeded");HANDLE file=CreateFileW(p.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);require(file!=INVALID_HANDLE_VALUE,"fresh output creation failed");DWORD written=0;const bool ok=WriteFile(file,body.data(),static_cast<DWORD>(body.size()),&written,nullptr)&&written==body.size()&&FlushFileBuffers(file);CloseHandle(file);require(ok,"metadata output write failed");}
void package(const std::string& value){require(!value.empty()&&value.size()<=256&&std::all_of(value.begin(),value.end(),[](unsigned char c){return std::isalnum(c)||c=='.'||c=='_';}),"current game package required");}
CandidateCollectionInputs begin(const CandidateReceiptCollectionRequest& r){fresh_output(r.output);package(r.game_package);auto bound=prepare_candidate_collection(r.inputs);const auto& i=bound.documents().at("input");if(i.contains("game_package"))require(i.at("game_package")==r.game_package,"game package input mismatch");bound.verify_unchanged();return bound;}
J probe(const CandidateReceiptCollectionRequest& r,const CandidateCollectionInputs& inputs){auto p=game_preflight(r.inputs.config_path.string(),r.inputs.capability_path.string());require(yes(p,"fingerprint_matches")&&!yes(p,"real_input_created"),"current profile/capability preflight failed");const auto config=load_config(r.inputs.config_path);p["current_game_apk_sha256"]=installed_apk_sha256(find_adb(),config.serial,r.game_package);require(p.at("capability_report_sha256")==inputs.context().at("capability_sha256"),"current capability hash differs");return p;}
void device_matches(const CandidateReceiptCollectionRequest& r,const CandidateCollectionInputs& inputs,const J& p){require(inputs.documents().contains("device"),"current device receipt missing");const auto& d=inputs.documents().at("device");require(d.at("schema")=="pas.current-device-profile-receipt.v1"&&d.at("evidence_kind")=="actual"&&yes(d,"pass"),"actual current device receipt malformed");for(const auto* key:{"source_commit","candidate_binary_sha256","profile_sha256","capability_sha256"})require(d.at(key)==inputs.context().at(key),"current device identity mismatch");require(d.at("game_package")==r.game_package&&d.at("game_apk_sha256")==p.at("current_game_apk_sha256")&&d.at("fixture_apk_sha256")==p.at("current_fixture_apk_sha256")&&d.at("device")==p.at("device")&&d.at("capture_geometry")==p.at("capture_geometry")&&d.at("corner_mapping")==p.at("corner_mapping"),"current device/profile/APK/mapping changed");}
GrpcEndpoint endpoint_for(const RuntimeConfig& c){if(c.endpoint.empty())return discover_endpoint(c.serial);GrpcEndpoint e;std::ifstream token(c.token_file,std::ios::binary);require(bool(token)&&bool(std::getline(token,e.token)),"gRPC token unavailable");if(!e.token.empty()&&e.token.back()=='\r')e.token.pop_back();require(!e.token.empty(),"gRPC token empty");e.target=c.endpoint;e.instance="explicit";return e;}
void capture_matches(const CandidateCollectionInputs& inputs){require(inputs.documents().contains("capture_rpc"),"current capture/RPC receipt missing");const auto& c=inputs.documents().at("capture_rpc");require(c.at("schema")=="pas.current-capture-rpc-qualification.v1"&&c.at("evidence_kind")=="actual"&&yes(c,"pass")&&yes(c,"real_capture_rpc_measured")&&yes(c,"all_attempts_verified")&&candidate_capture_metrics_valid(c.at("metrics")),"actual capture/RPC complete attempted window missing");for(const auto* key:{"source_commit","candidate_binary_sha256","profile_sha256","capability_sha256"})require(c.at(key)==inputs.context().at(key),"capture/RPC identity mismatch");require(c.at("device_receipt")==inputs.documents().at("input").at("device"),"capture/RPC device receipt join");}
std::uint32_t header_sequence(const Frame& frame){require(frame.stride==frame.width*3&&frame.width>=320&&frame.height>=660,"fixture geometry invalid");const auto pixel=static_cast<std::size_t>(50)*frame.stride+84*3;return (std::uint32_t(frame.rgb.at(pixel))<<16)|(std::uint32_t(frame.rgb.at(pixel+1))<<8)|frame.rgb.at(pixel+2);}
void foreground(const RuntimeConfig& c){const auto b=adb_call(find_adb(),{"-s",c.serial,"shell","dumpsys","window"},5000);const std::string s(b.begin(),b.end());const auto at=s.find("mCurrentFocus=");require(at!=std::string::npos&&s.substr(at,s.find('\n',at)-at).find("org.pas.touchfixture.cpp")!=std::string::npos,"native touch fixture must be foreground; no automatic install or launch");}
J fixture_mapping(const RuntimeConfig& c){foreground(c);HostClock clock;GrpcCapture capture(clock,endpoint_for(c),runtime_capture_options(c));GrpcTouch touch(clock,endpoint_for(c),PixelCoordinateMap(c.width,c.height,c.touch_width,c.touch_height,c.touch_rotation),c.touch_width,c.touch_height,5,std::chrono::milliseconds(c.touch_timeout_ms));
    J rows=J::array();bool first_release=false,release_ok=false;const auto release=[&]{if(!first_release){first_release=true;const auto r=touch.release_all();release_ok=r.failed_ids.empty()&&r.unknown_ids.empty();}return release_ok;};
    try{for(int which=0;which<6;++which){foreground(c);const auto before_frame=capture.snapshot(std::chrono::milliseconds(2000));const auto before=decode_touch_evidence(before_frame,header_sequence(before_frame));require(before.complete&&before.active==0,"fixture initial signature/contact state unknown");std::vector<ExpectedPointer> expected;const auto count=which==5?5:1;
        for(int id=0;id<count;++id){const int x=which<4?((which%2)?c.width-1:0):static_cast<int>(c.width*(.15+id*.16));const int y=which<4?((which/2)?c.height-1:0):static_cast<int>(c.height*(.45+(id%2)*.12));const auto receipt=touch.inject({std::uint64_t(id+1),id,Phase::down,double(x),double(y),clock.now_ns(),before_frame.sequence});require(receipt.success,"fixture Down unknown; never retried");expected.push_back({1,id,x,y});}
        if(which>=4){std::this_thread::sleep_for(std::chrono::milliseconds(70));const int x=static_cast<int>(c.width*.15)+30,y=static_cast<int>(c.height*.45)+12;const auto receipt=touch.inject({1,0,Phase::move,double(x),double(y),clock.now_ns(),before_frame.sequence});require(receipt.success,"fixture Move unknown");expected.push_back({2,0,x,y});}
        if(which==5){const auto middle=capture.snapshot(std::chrono::milliseconds(1000));const auto evidence=decode_touch_evidence(middle,before.sequence);require(evidence.complete&&evidence.active==5&&evidence.downs-before.downs==5,"five contacts not verified by current fixture pixels");}
        std::this_thread::sleep_for(std::chrono::milliseconds(which>=4?160:40));for(int id=0;id<count;++id){const int x=which<4?((which%2)?c.width-1:0):static_cast<int>(c.width*(.15+id*.16))+(id==0?30:0);const int y=which<4?((which/2)?c.height-1:0):static_cast<int>(c.height*(.45+(id%2)*.12))+(id==0?12:0);const auto receipt=touch.inject({std::uint64_t(id+1),id,Phase::up,double(x),double(y),clock.now_ns(),before_frame.sequence});require(receipt.success,"fixture Up unknown");expected.push_back({3,id,x,y});}
        TouchEvidence after;const auto deadline=clock.now_ns()+2'000'000'000LL;do{const auto frame=capture.snapshot(std::chrono::milliseconds(2000));after=decode_touch_evidence(frame,before.sequence);if(after.complete&&after.active==0&&after.ups-before.ups==count)break;std::this_thread::sleep_for(std::chrono::milliseconds(10));}while(clock.now_ns()<deadline);
        const auto check=verify_touch_path(after,expected,4,0);require(check.passed&&after.downs-before.downs==count&&after.ups-before.ups==count&&after.cancels==before.cancels,"fixture current pixel pointer path/mapping failed");rows.push_back({{"case",which<4?"corner-"+std::to_string(which):(which==4?"hold_move":"five")},{"attempts",expected.size()},{"verified",expected.size()},{"pass",true}});
    }require(release(),"fixture first release not verified");}catch(...){try{release();}catch(...){}throw;}
    return {{"schema","pas.current-fixture-mapping-aggregate.v1"},{"pass",true},{"failed",0},{"unknown",0},{"final_active_contacts",0},{"release_verified",release_ok},{"cases",rows},{"path_tolerance_px",4},{"max_contacts_verified",5},{"pixels_persisted",false},{"touch_trace_persisted",false}};
}
