void collect_candidate_device_receipt(const CandidateReceiptCollectionRequest& r){auto inputs=begin(r);auto out=envelope(inputs,"pas.current-device-profile-receipt.v1");try{const auto p=probe(r,inputs);const auto c=load_config(r.inputs.config_path);out.update({{"serial",c.serial},{"game_package",r.game_package},{"game_apk_sha256",p.at("current_game_apk_sha256")},{"fixture_apk_sha256",p.at("current_fixture_apk_sha256")},{"device",p.at("device")},{"capture_geometry",p.at("capture_geometry")},{"corner_mapping",p.at("corner_mapping")},{"real_input_created",false},{"pass",true}});inputs.verify_unchanged();write_output(r.output,out);}catch(const std::exception& e){out["status"]="NOT_READY";out["reason"]=e.what();if(!fs::exists(r.output))write_output(r.output,out);throw;}}

void collect_candidate_capture_rpc_receipt(const CandidateReceiptCollectionRequest& r){auto inputs=begin(r);auto out=envelope(inputs,"pas.current-capture-rpc-qualification.v1");try{const auto p=probe(r,inputs);device_matches(r,inputs,p);const auto c=load_config(r.inputs.config_path);HostClock clock;GrpcCapture capture(clock,endpoint_for(c),runtime_capture_options(c));std::mutex mutex;std::vector<double> full,measured,copy,residence,intervals;Nanoseconds previous_measured=0;std::exception_ptr error;std::atomic<Nanoseconds> first=0;std::atomic<bool> closing=false;
    const auto opened=clock.now_ns();std::jthread worker([&](std::stop_token stop){try{capture.stream(stop,[&](Frame&& f){const auto now=clock.now_ns();Nanoseconds expected=0;first.compare_exchange_strong(expected,f.capture_complete_ns);const auto start=first.load()+candidate_capture_warmup_ns,end=start+candidate_capture_measurement_ns;std::lock_guard lock(mutex);require(full.size()<100000&&f.receive_start_ns&&f.notification_received_ns&&f.copy_start_ns&&f.copy_end_ns&&*f.notification_received_ns>=*f.receive_start_ns&&*f.copy_end_ns>=*f.copy_start_ns&&now>=f.pixels_ready_ns,"capture timing/capacity incomplete");full.push_back(double(*f.notification_received_ns-*f.receive_start_ns)/1e6);if(f.capture_complete_ns>=start&&f.capture_complete_ns<=end){if(previous_measured)intervals.push_back(double(f.capture_complete_ns-previous_measured)/1e6);previous_measured=f.capture_complete_ns;measured.push_back(full.back());copy.push_back(double(*f.copy_end_ns-*f.copy_start_ns)/1e6);residence.push_back(double(now-f.pixels_ready_ns)/1e6);}});if(!closing&&!stop.stop_requested())throw std::runtime_error("capture stream ended before window");}catch(...){std::lock_guard lock(mutex);error=std::current_exception();}});
    Nanoseconds ended=0;while(true){{std::lock_guard lock(mutex);if(error)break;}const auto now=clock.now_ns(),f=first.load();if(!f&&now-opened>=candidate_capture_ready_ns){std::lock_guard lock(mutex);error=std::make_exception_ptr(std::runtime_error("capture ready budget expired"));break;}if(f&&now>=f+candidate_capture_warmup_ns+candidate_capture_measurement_ns){ended=now;break;}std::this_thread::sleep_for(std::chrono::milliseconds(10));}
    closing=true;worker.request_stop();capture.cancel();worker.join();if(error)std::rethrow_exception(error);require(first.load()>=opened&&first.load()-opened<=candidate_capture_ready_ns,"capture ready window incomplete");const auto stats=capture.stats();require(stats.valid==full.size(),"capture accepted denominator mismatch");J metrics={{"attempted_notifications",stats.valid+stats.inactive+stats.invalid+stats.relative_stale_drops},{"accepted_frames",stats.valid},{"inactive_notifications",stats.inactive},{"invalid_notifications",stats.invalid},{"relative_stale_drops",stats.relative_stale_drops},{"source_gaps",stats.source_gaps},{"failed",0},{"unknown",0},{"ready_budget_ns",candidate_capture_ready_ns},{"warmup_ns",candidate_capture_warmup_ns},{"measurement_ns",candidate_capture_measurement_ns},{"ready_start_ns",opened},{"first_frame_ns",first.load()},{"measurement_start_ns",first.load()+candidate_capture_warmup_ns},{"measurement_end_ns",ended},{"window_complete",true},{"source_absolute_age",nullptr},{"performance_pass",nullptr},{"full_rpc_read_ms",distribution(full)},{"measurement_rpc_read_ms",distribution(measured)},{"measurement_copy_ms",distribution(copy)},{"measurement_host_residence_ms",distribution(residence)},{"measurement_frame_interval_ms",distribution(intervals)}};require(candidate_capture_metrics_valid(metrics),"capture attempted/timing window invalid");out.update({{"metrics",metrics},{"real_capture_rpc_measured",true},{"all_attempts_verified",true},{"device_receipt",inputs.documents().at("input").at("device")},{"performance_pass",nullptr},{"warnings",J::array()},{"pass",true}});if(metrics.at("measurement_host_residence_ms").at("p99").get<double>()>10)out["warnings"].push_back("host residence p99 exceeds original diagnostic 10ms warning");if(!intervals.empty()&&*std::max_element(intervals.begin(),intervals.end())>150)out["warnings"].push_back("capture gap exceeds original diagnostic 150ms warning");inputs.verify_unchanged();device_matches(r,inputs,probe(r,inputs));write_output(r.output,out);
}catch(const std::exception& e){out["status"]="NOT_READY";out["reason"]=e.what();if(!fs::exists(r.output))write_output(r.output,out);throw;}}

void collect_candidate_physical_receipt(const CandidateReceiptCollectionRequest& r){auto inputs=begin(r);const auto& i=inputs.documents().at("input");const bool review=candidate_collection_review_mode(i);auto out=envelope(inputs,review?"pas.current-physical-qualification.v1":"pas.current-physical-owner-observation.v1");try{device_matches(r,inputs,probe(r,inputs));capture_matches(inputs);out["device_receipt"]=i.at("device");out["capture_rpc_receipt"]=i.at("capture_rpc");
    if(review){const auto& owner=inputs.documents().at("physical_owner_observation");const auto& gold=inputs.documents().at("physical_review");require(candidate_physical_review_valid(owner,gold,i.at("physical_owner_observation")),"independent current physical review incomplete/unknown/historical");for(const auto* key:{"source_commit","candidate_binary_sha256","profile_sha256","capability_sha256"})require(owner.at(key)==inputs.context().at(key),"owner observation current identity mismatch");require(owner.at("device_receipt")==i.at("device")&&owner.at("capture_rpc_receipt")==i.at("capture_rpc"),"owner observation current device/capture join");out.update({{"owner_observation",i.at("physical_owner_observation")},{"independent_review",i.at("physical_review")},{"real_input_created",true},{"same_current_pixel_owner_verified",true},{"five_contact_mapping_verified",true},{"identity_1519_verified",true},{"failed",0},{"unknown",0},{"final_active_contacts",0},{"release_verified",true},{"phases",gold.at("phases")},{"pass",true},{"status","PHYSICAL_RECEIPT_PASS"},{"physical_gold",true}});
    }else{const auto c=load_config(r.inputs.config_path);out["fixture_mapping"]=fixture_mapping(c);std::cout<<"Fixture mapping complete; select the authorized current chart and press Play once. This round counts toward the single pass.\n"<<std::flush;CandidatePhysicalAggregate aggregate;auto single=std::make_shared<std::atomic<bool>>(false);CandidatePhysicalPermit permit([inputs,single]{require(!single->exchange(true),"physical collection permit already consumed");inputs.verify_unchanged();},r.inputs.config_path,r.inputs.capability_path);run_current_candidate_physical_qualification(permit,r.inputs.config_path.string(),r.inputs.capability_path.string(),aggregate);out.update({{"owner_aggregate",aggregate.report()},{"real_input_created",true},{"physical_gold",false},{"pass",false},{"status","NOT_READY"},{"reason","independent current live-pixel semantic review required after actual owner completion"}});}
    inputs.verify_unchanged();device_matches(r,inputs,probe(r,inputs));write_output(r.output,out);
}catch(const std::exception& e){out["status"]="NOT_READY";out["reason"]=e.what();if(!fs::exists(r.output))write_output(r.output,out);throw;}}
